/* What's new: plain-English notes, newest first. Add one entry per version. */
const NEWS = [
  { v: 'v255', items: ['Tidied the built-in boiler list: Glow Worm is now written the same way everywhere, and boiler types (combi, system, regular) stay as the data sheet gives them.'] },
  { v: 'v254', items: ['Fixed: the Ideal I-Mini 24, 30 and 35kW now show their GC number and figures.'] },
  { v: 'v253', items: ['Added Glow-worm (Energy, Home, Sustain, Ultimate 3, Easicom 3), Alpha (E-Tec, E-Tec Plus, Evoke, InTec), Ferroli (T-One, Optimax HE Plus, Bluehelix) and Viessmann Vitodens 050-W boilers with their manufacturer figures.'] },
  { v: 'v252', items: ['Added Vaillant (ecoFIT, ecoTEC sustain, Home, ecoTEC plus), Baxi (200, 400, 600, 800 combi and system) and Vokera (Evolve, Unica Max, Vibe Max, Easi-Heat) boilers with their manufacturer figures.'] },
  { v: 'v251', items: ['Added Ideal boilers with their manufacturer figures: Logic Max Combi and Combi2, i-mini2, Vogue Max (combi and system), Logic Max System and System2, Logic Max Heat and Heat2. Search by model or GC number.'] },
  { v: 'v250', items: ['Model search: type a GC number (for example 41-406-47) in the model box and tap the boiler. The make, model and GC number are all filled in, even if you had picked the wrong make.'] },
  { v: 'v249', items: ['Added the Worcester Greenstar 2000 (25, 30kW), 8000 Life (30, 35kW) and 8000 Style (30, 35, 40kW) combi boilers with their manufacturer figures. CO2 can now be shown as a range, as some manuals print it, and CO can have a separate limit at minimum rate.'] },
  { v: 'v248', items: ['Added the Worcester Greenstar 30CDi and 40CDi (conventional) with their manufacturer figures.'] },
  { v: 'v247', items: ['More Worcester boilers with figures: Greenstar Ri ErP (12, 15, 18, 24), Greenstar 4000 combi (25 and 30kW) and Greenstar R29 HE and R40 HE. The Greenstar 12, 15 and 18Ri now have fan pressure pass and fail ranges.'] },
  { v: 'v246', items: ['Built-in boiler figures now include the Worcester Greenstar 4000 System (12, 15, 18, 21 and 24kW) with GC numbers, CO2, CO, heat input, gas pressure and fan pressure pass and fail ranges.'] },
  { v: 'v245', items: ['Built-in boilers now include the Worcester Greenstar 12Ri, 15Ri and 18Ri alongside the 24Ri, each with its GC number and manufacturer figures. These are regular (heat only) boilers, so the 24Ri is now listed as Heat only.'] },
  { v: 'v244', items: ['Boilers built into the app now also appear in everyone\'s Price list, so they can be used on quotes. Delete one and it stays deleted.'] },
  { v: 'v243', items: ['The Greenstar 24Ri now shows its 5-year manufacturer warranty.'] },
  { v: 'v242', items: ['Price list: the boiler type box is wide enough to read again, and the kW box is small.'] },
  { v: 'v241', items: ['The boiler card shows only the manufacturer\'s own figures again; the fan pressure line no longer has extra wording. Each boiler in the Price list now has fan pressure PASS from/to and FAIL from/to boxes you can edit; the fan reading turns green or red from them.'] },
  { v: 'v240', items: ['Boiler figures are now built into the app for everyone. The Greenstar 24Ri is there already, and more boilers will arrive in updates. Fan pressure now turns green from -3.1 down to -10 and red for -3 to 0 (you do not need to type the minus: it is added for you). Boilers you save yourself in the Price list still work, and yours are used first.'] },
  { v: 'v239', items: ['Adding boiler figures from a data sheet is quicker: the boxes use the sheet\'s own wording in the same order, and you can copy the figures from a similar boiler and change what differs.'] },
  { v: 'v238', items: ['Fix: a half-typed model (such as "gree") no longer fills in a GC number. The boiler is only matched once you pick it or type its full model name.', 'The (i) next to the model shows the boiler\'s full data sheet. The (i) next to a reading shows only the figures that test needs, for example operating pressure shows just the minimum inlet pressure. No (i) appears when there is no saved card for the model.', 'Fix: the (i) buttons no longer get rebuilt over and over, which could make a tap on your phone do nothing.'] },
  { v: 'v237', items: ['Fix: the model search box now finds the Greenstar 24Ri straight away, without opening the Price list first.'] },
  { v: 'v236', items: ['The GC number now follows the model: change the model and the GC number changes with it. A GC number you type yourself is never overwritten.'] },
  { v: 'v235', items: ['Appliance model is now a search box: start typing and boilers from your Price list appear. Tap one to fill in the model and its GC number. The (i) panel now shows the boiler\'s data sheet in the manufacturer\'s own wording.'] },
  { v: 'v234', items: ['Fan pressure: the (i) button now explains the test in plain words and links to a fuller page. It shows on Worcester boilers even if you have not saved their figures.'] },
  { v: 'v233', items: ['When you type a boiler model that is saved in your Price list with its GC number, the GC number on the service or gas check fills in for you.'] },
  { v: 'v232', items: ['Manufacturer figures: when a reading is outside the boiler\'s figure, a pop-up says "Out of range" and on a service lets you choose Pass or Fail for that check.'] },
  { v: 'v231', items: ['Warning notices: when a check or service has a failure, the review step now asks "Create a warning notice?" with Yes and No buttons, instead of forcing one. You can still create one later.'] },
  { v: 'v230', items: ['Manufacturer figures for boilers. Save a boiler\'s data-sheet limits in the Price list (Boiler), and when you pick that boiler on a service or gas check, an (i) button beside each reading shows the figures. CO, CO2, ratio and gas inlet pressure turn green or red against them. It is a guide only and never changes a result.'] },
  { v: 'v229', items: ['Sample data now includes a boiler service due in 3 weeks and a gas check that is 5 days overdue, so you can try out the Annual reminders screen.'] },
  { v: 'v228', items: ['Today: tap an overdue invoice to open it. The Chase button is still there.'] },
  { v: 'v227', items: ['Faster start-up. The app now opens straight from the copy kept on your phone, so it no longer waits on a weak signal. A new version downloads quietly in the background and starts the next time you open the app.'] },
  { v: 'v226', items: [
    'Forms: after you answer a Pass / Fail or Yes / No question for the first time, the form scrolls to the next blank one. You can switch this off in Settings.',
    'Appointments: Mark as done, Add to calendar and Delete now sit under a More button, so the page is shorter.',
    'Customers: Call, Text, Navigate and New job buttons across the top of every saved customer.',
    'Today: the next job has a Start the forms button, and the rest of the day is a timeline showing the drive between jobs.',
    'Search: a magnifying glass at the top finds any customer, address, certificate, quote or invoice.',
    'Friendlier empty screens, and a short first-time tour for new accounts (Settings has Show the tour).'] },
  { v: 'v225', items: ['Tapping a finished job (a certificate, service, quote or notice) in a list or under a customer\u2019s previous jobs now takes you straight to the screen where you can open it, send it, edit it, and accept or decline it if it is a quote. The review page in between is gone.'] },
  { v: 'v224', items: ['Gas safety check: equipotential bonding now has an NA choice (for example a plastic incoming supply), the same as the pipework checks. NA does not trigger a warning notice. Fail still does.'] },
  { v: 'v223', items: ['Gas safety check: if you reduce the number of appliances, any defects noted against the appliance you took off are removed too, so the Review page no longer asks you to complete them.'] },
  { v: 'v222', items: ['Gas safety check: new \u201cVisual inspection only?\u201d choice for each appliance. Choose Yes when no physical checks could be done and the tests are skipped. The certificate then says \u201cVisual inspection only\u201d against that appliance.'] },
  { v: 'v221', items: ['Each property on a customer can now have its own contact: a name, phone number and access note (for example the tenant at a letting agent\u2019s house). It shows on the appointment with a Call button, on the form under the job address, and as \u201cSite contact\u201d in the site details of all the certificates and warning notices (the access note is never printed).', 'On an appointment, \u201cStart the forms for this job\u201d is now at the top, just under the Navigate button.'] },
  { v: 'v219', items: ['Pop-up pages (Route, Plan my day, New and others) now close when you swipe them down, so you no longer have to scroll to the bottom to go back.'] },
  { v: 'v218', items: ['New \u201cSame as job address\u201d button under the client address on forms, for customers who live at the property. One tap fills the client address from the job address.'] },
  { v: 'v217', items: ['Auto schedule now arranges the day for you. Every time you save a booking with Auto schedule ticked, the app works out the drive from your start postcode and puts all that day\u2019s Auto schedule jobs in order (nearest first or furthest first, as chosen in Settings), with the drive added between them. Jobs not ticked Auto schedule keep their time. It needs a postcode on the job and a start postcode in Settings \u2192 Calendar; without them the job just goes in the first blank slot.'] },
  { v: 'v216', items: ['Booking with Auto schedule ticked no longer asks \u201cYou already have\u2026 book anyway?\u201d. The job is put into the first blank slot of the day (from your day start time) and Plan my day then arranges the jobs nearest first or furthest first, as chosen in Settings.'] },
  { v: 'v215', items: ['Today: the drive time line stays blank, instead of showing a trial message, when the server refuses the request. A fix on the server for free-pass accounts follows.'] },
  { v: 'v214', items: ['Today: if Google sends back nothing for the drive time, the line now says so instead of staying blank.'] },
  { v: 'v213', items: ['Today: when the drive time to your next appointment cannot be worked out, it now says why (for example location not allowed, no start postcode, daily limit reached or Google could not find the route) instead of showing nothing.'] },
  { v: 'v212', items: ['Choose your maps app: Settings \u2192 App & account \u2192 Navigation lets you pick Google Maps, Apple Maps or Waze for every Navigate button. Apple Maps and Waze take one address at a time, so Start route on the Route sheet opens the first job; Google Maps still plans the whole day.'] },
  { v: 'v211', items: ['Booking an appointment: \u201c+ Add a new address\u201d is now at the top of the customer\u2019s address list instead of the bottom, so you do not have to scroll past hundreds of addresses.'] },
  { v: 'v210', items: ['Calendar: jobs ticked Auto schedule that are waiting for Plan my day no longer show as clashing with each other. They show \u201cPlan my day will set the time the day before\u201d instead. Real clashes (for example a fixed-time job overlapping another) still show.'] },
  { v: 'v209', items: ['Administrator functions updated.'] },
  { v: 'v208', items: ['Date paid: once an invoice is ticked as Paid, a Date paid box appears in the Dates section so you can put in the day the money actually arrived (the PAID stamp, the invoice and your statements then use that date). The overdue prompt and the chase sheet now have \u201cPaid earlier \u2013 choose the date\u201d, which marks it paid and takes you straight to the date box.'] },
  { v: 'v207', items: ['PDF fix: on the gas safety, boiler service, legionella, air conditioning and commissioning records, the date under the engineer\u2019s signature was sitting outside the box. The signature area is a little shorter so the name, Gas Safe ID and date all sit inside.'] },
  { v: 'v206', items: ['Extra security: the app now tells the browser exactly which sites it may talk to and which scripts it may run, so nothing unexpected can be injected into a page. You will not notice any difference.'] },
  { v: 'v205', items: ['On a new quote, the property heading now says \u201cWork address\u201d instead of \u201cProperty inspected\u201d.'] },
  { v: 'v204', items: ['Better on a laptop: on a wide screen the menu moves to a panel down the left side, the page is wider, buttons and rows highlight when you hover over them, and keyboard focus is clearer. Phones and tablets look exactly as before. Forms you fill in keep the narrower column so they stay easy to read.', 'Price list now sits at the top of Settings \u2192 Money, on its own, because quotes and invoices both use it (on an invoice tap \u201c+ Add from my price list\u201d).'] },
  { v: 'v203', items: ['Settings tidied up. There are now five tabs: Business (your details, logos, engineer, services you offer), Money (invoice numbering and terms, bank details, prices, discount, quotes), Messages (every piece of wording in one place, plus automatic reminder emails and how emails are sent), Calendar, and App & account (subscription, backup, appearance, updates, tools). Help guide, What\u2019s new and Feedback are now one small row at the top. Nothing you had saved has moved or been lost.'] },
  { v: 'v202', items: ['Chromebook and computer email: if the computer has no mail program, Send now offers Gmail on the web or Outlook on the web, opened with the customer\u2019s address, subject and message filled in (attach the PDF from Downloads). Reminder, calendar and quote-chase emails do the same. Choose your email once in Settings \u2192 Messages \u2192 Sending emails.'] },
  { v: 'v201', items: ['Appliance alert: on a customer\u2019s Appliances list, any appliance with an open immediately dangerous or at risk defect now shows a red bar (\u201c2 open safety defects \u2013 tap to see\u201d). Tap it and the history opens at the fault, outlined in red. Once you have recorded \u201cCustomer informed\u201d it turns into a quieter amber note, and when a defect is marked fixed the bar goes.'] },
  { v: 'v200', items: ['Safety defects to follow up: a new \u201cCustomer informed\u201d button records that the customer was told about the defect and chose not to have it repaired now. You add a note, it comes off the follow-up list, and it is written into the appliance history (Customer \u2192 Appliances \u2192 History) as \u201cCustomer informed\u201d with the date and your note. Fixed defects now show there too, and either can be reopened.'] },
  { v: 'v199', items: ['Less retyping: (1) a new boiler commissioning checklist fills the make, model and system type from the quote for that customer. (2) The oil warning notice fills from the oil boiler service or oil tank check (appliance, location, make, model, serial, classification and defect); the review step now offers \u201cFill in the oil warning notice\u201d when a defect is at risk or immediately dangerous. (3) Gas safety records have an optional Serial number box per appliance; it copies forward on repeat visits and prints on the certificate and the warning notice. (4) Legionella, air conditioning and oil tank checks now copy the property, system and tank details from your last visit, like the gas and boiler service forms.'] },
  { v: 'v198', items: ['Warning notice: the notice now fills itself in from the gas safety check. Each appliance that failed a check or has an immediately dangerous / at risk defect becomes its own fault, with its location, type, make, model and GC number, the failed checks, the defect wording and action taken, and the ID or AR already chosen. The serial number comes from an earlier service of the same boiler if you have one. A new GC number box has been added to the notice and its PDF.'] },
  { v: 'v197', items: ['Saved defect wording: under each defect box there are buttons for your usual defects. Tap one to fill it in; on a gas safety record it also fills the classification and the action taken. Tap \u201c+ Save this wording\u201d to keep a new one. Manage the list in Settings \u2192 Messages \u2192 Saved defect wording.'] },
  { v: 'v196', items: ['Safety defects to follow up: any immediately dangerous or at risk defect on a finished gas or oil record now stays on a list until you mark it fixed. Today shows how many are open and turns red when one is over a week old. For each you can text the customer, book a return visit, mark it fixed, or open the record.'] },
  { v: 'v195', items: ['Appliance history: on a customer, open Appliances and tap History under any appliance. It lists every visit for that appliance at that property, newest first, with the readings, failed checks and defects, and warns you when the same check has failed on the last few visits running.'] },
  { v: 'v194', items: ['Appliance details now fill in by themselves for a repeat customer. When you pick the customer and address on a gas safety, boiler service or oil service record, the make, model, location and flue are copied from your last visit there, so you only do the checks. Test readings and signatures are left blank. You can switch it off in Settings \u2192 App & account \u2192 Records.'] },
  { v: 'v193', items: ['Owner page: each user now shows when they were last active (when their data last synced), as well as their last sign-in. The sign-in date only changes when someone types their password, so a person who stays signed in looked like they had stopped using the app.'] },
  { v: 'v192', items: ['Boiler service and oil boiler service: a new Yes / No question, \u201cHas a full strip down service been carried out?\u201d, replaces the required boiler age. The age is still there as an optional box. The answer is printed on the PDF.'] },
  { v: 'v191', items: ['New backup: Settings \u2192 Back up as folders (zip). It makes one zip file with a folder for each customer holding their certificates, invoices and photos (named like "Gas Safety Record 2026-10-15 - Defect 1 - photo 1"), so you can open it on a computer and browse it. You can add a password. Restore from a backup also opens these zip files. The old single-file backup is still there.'] },
  { v: 'v190', items: ['Gas safety record: defects are now written at the bottom of each appliance, so you note a fault while you are looking at it instead of remembering it all until the Defects step. They still appear on the Defects step and on the PDF (marked with the appliance). You can note up to 8 defects.'] },
  { v: 'v189', items: ['Fixed: on the Sign off step a white box covered the lower half of the signature while you signed. The signature itself was always saved correctly; only the box on screen was wrong.'] },
  { v: 'v188', items: ['Plan my day order: in Settings \\u2192 Calendar choose Closest first, furthest last (the default) or Furthest first, closest last.'] },
  { v: 'v187', items: ['Drive times are remembered between postcodes for 45 days, and Plan my day works out all the legs in a single lookup, so regular customers and repeat plans cost almost nothing.'] },
  { v: 'v186', items: ['Auto schedule tick box on the appointment, under the start time. Plan my day only moves jobs that are ticked, and fits them around the ones you have agreed a fixed time for. If none are ticked it can move them all.'] },
  { v: 'v185', items: ['Plan my day: on the Route sheet, tap Plan my day. It puts the jobs nearest to your start postcode first and the furthest last, gives each its time slot and adds the drive between jobs (first job 9 to 10, next one 10:10 if it is 10 minutes away). You see the new times first and nothing changes until you tap Put these times in my calendar. Then Text the next customer sends each their arrival time, one tap at a time. Set the start time in Settings \u2192 Calendar \u2192 Day starts at.'] },
  { v: 'v184', items: ['On the Route sheet, tap a job to open its appointment. The list is always in order of start time, so if you move an appointment later it moves down the route and the drive times are worked out again for the new order.'] },
  { v: 'v183', items: ['Running late? When you open a job that has already started, or that you will not reach on time, there is a Reschedule button at the top. Pick a new day and time, and move it with or without a text to the customer saying sorry and asking if the new time is OK.'] },
  { v: 'v182', items: ['New setting: Settings \u2192 Calendar \u2192 Start the day\u2019s route from. Type the postcode you set off from (home or your yard), or tap Copy the postcode from my business address. Tomorrow\u2019s route and the first drive of the day use it.'] },
  { v: 'v181', items: ['Tomorrow\u2019s route now starts from the postcode of your address in Settings. It shows the drive from there to the first job, says when to leave to be there on time, and includes that drive in the total. Today, if your phone\u2019s location is not available, it does the same from your Settings address.'] },
  { v: 'v180', items: ['If an accepted quote is booked in the calendar and you then mark it Declined, the app asks whether to remove it from the calendar too.'] },
  { v: 'v179', items: ['Fixed: if you delete the appointment you booked from an accepted quote, the quote no longer says it is booked in. It goes back to Book the job.'] },
  { v: 'v178', items: ['Tomorrow\u2019s route no longer shows a drive from where you are now, since you plan it from tonight. That line and the extra minutes in the total are for today only.'] },
  { v: 'v177', items: ['The Route total now includes the drive from where you are to the first job.'] },
  { v: 'v176', items: ['Drive times now read \u201c2 mins\u201d instead of \u201c2 min\u201d (and \u201c1 min\u201d for one).'] },
  { v: 'v175', items: ['The Next job card now shows \u201cSet off in 12 min to arrive on time\u201d under the drive time when you can still make it.'] },
  { v: 'v174', items: ['The Route sheet now shows the drive from where you are (your phone\u2019s location) to the first job, just under the job count. It is green if you will arrive in time, amber if you will be up to 15 minutes late and red if you will be later than that. The same colours show on the Next job card.', 'The On my way text now says \u201cI will be with you in about 15 minutes\u201d, and adds a sorry if you are running behind schedule. Turn it off in Settings \u2192 Calendar \u2192 Add my travel time to the text.'] },
  { v: 'v172', items: ['The appointment now has a separate Postcode box under Address of the job, like the forms. Tapping a job with no postcode on the Route sheet takes you straight to it.'] },
  { v: 'v171', items: ['The next job now shows the drive time from where you are, using your phone\u2019s location (your phone asks permission the first time). It is used for that one lookup and not saved. Switch it off in Settings \u2192 Calendar to measure from your last job or business address instead.', 'On the Route sheet, when a job has no postcode, its name in the note is now a button: tap it and the appointment opens with the cursor in the address box.'] },
  { v: 'v170', items: ['The next job on Today now shows the drive time to it, from the job before it or, for the first job of the day, from your business address in Settings. It needs a postcode on the job address, and is remembered for the day so it only asks once.'] },
  { v: 'v169', items: ['Drive times now appear by themselves when you open the Route sheet, and are remembered so opening it again does not ask again. Jobs whose address has no postcode are left out and flagged, because a short address like 2A Ashfield can match the wrong town.'] },
  { v: 'v168', items: ['Drive times on the Route sheet. Tap Show drive times to see how long each leg between your stops takes and the total for the day. They are estimates without live traffic, and a daily limit stops it being overused.'] },
  { v: 'v167', items: ['Appliance register: each customer has an Appliances tab listing every boiler and appliance at each property (make, model, GC number, serial number, flue, last visit and when it is next due). One tap starts the next service or gas safety record with the details already filled in.', 'Chase overdue invoices: the Invoices screen shows what is overdue with a Chase button, and each overdue invoice shows how many days late it is and how many times you have chased it. Pick Text, WhatsApp or Email (with the invoice attached). Nothing is sent until you tap send. You can also mark it paid from the same screen.', 'Quote to invoice: an accepted quote now has Book the job and Create invoice from this quote. The invoice has the customer, address and every priced line from the quote, so nothing is retyped.', 'Route for the day: on Today, the Route button lists the day\u2019s jobs in appointment order with a Go link for each, and Start route opens them all as one trip in your maps app. Switch to Tomorrow to plan the night before: each customer with a mobile number has a Text ETA button that writes \u201cI will be with you around 9am tomorrow\u201d from the time booked in the calendar. Nothing is sent until you tap send.', 'A new Today screen. Services is now Today: it shows the day and what needs doing, with one New button that opens a short list of everything you can start (records, quotes and invoice). The next job has Call, On my way and Navigate buttons, then later today, annual checks due this week and overdue invoices with a Chase button. The setup warning is now a short checklist.', 'A new look: bolder, easier to read headings and labels, quieter buttons with gold kept for the main action, and a colour dot with a word for status. Settings → App → Appearance has a light mode for bright sun, or leave it matching your phone.'] },
  { v: 'v166', items: ['First time you open the app it now shows a Loading screen straight away instead of a blank page while it downloads. The app also opens faster: the PDF maker now loads just after the first screen appears rather than before it, which cuts about a third off the first-time wait on a slow signal.'] },
  { v: 'v165', items: ['Six new oil tools for oil boiler engineers (Tools tab, shown when What work do you do? is Oil or Gas and oil): tank volume and bund check (110%), burner firing rate (nozzle size and pressure to litres per hour and kW), combustion efficiency check, fuel use and running cost (old boiler against new), oil supply pipe sizing, and ventilation sizing. Each shows its workings, goes into the calculation report, and can be hidden in Settings → Tools. The ventilation figures and pipe sizing are worked-out guides, so check them against Approved Document J and OFTEC.', 'Oil PDFs: the Engineer and Client sign-off boxes are taller, so the Date line no longer sits outside the box.'] },
  { v: 'v164', items: ['Oil forms now use oil-specific choices: makes (Grant, Firebird, Worcester Bosch, Warmflow, Boulter Buderus, Trianco, Viessmann), places an oil boiler sits (integral or detached garage, boiler house, external, cellar), flue types (conventional, balanced, vertical for external boilers) and fuel grades (kerosene 28 sec, gas oil 35 sec, HVO).'] },
  { v: 'v163', items: ['For oil boiler engineers: Settings → App → Services to show now has What work do you do? (Gas, Oil, or Gas and oil). Oil adds an oil boiler service record, oil tank check, installation completion report, landlord oil check, warning and advice notice, tank spillage and fire risk assessment, and condensing boiler assessment, plus an OFTEC registration number in Settings → Business, and hides the gas-only forms and tools. These are the app’s own records based on the usual OFTEC headings, not OFTEC-issued certificates.'] },
  { v: 'v162', items: ['If a subscription ends, the Tools (gas rate, pipe sizing, tightness test volume, heat loss and the PDF report) are now switched off too. Records stay viewable and exportable.', 'Texts and emails that greet the customer now use Mr Smith instead of just Mr when the name starts with a title (on my way and day-before texts, quote chase, quote PDF greeting). Names without a title still use the first name.', 'A red reminder with a Subscribe now button appears when there are two days or fewer left on the free trial, and when a subscription has not renewed and is about to go read-only.'] },
  { v: 'v161', items: ['Quotes now remember when they were sent. Sharing or emailing a quote records the day, the Quotes tab shows Sent 13/10 or Not sent yet (with a Not sent filter), and the two-week chase counts from the day you sent it. Sent it another way? Tap Mark as sent on the quote.', 'Price list: every item has a Supplier details box for where the price came from and where to order it (supplier, phone, website, product code). It is shown under the item, and goes into and comes out of the Excel download and import. Your customers never see it.', 'Settings → App now starts with the App version box, so Update app now is the first thing you see.'] },
  { v: 'v160', items: ['Calendar: appointments that overlap now show a red Clash tag and say who they clash with. You already got a warning when saving a clashing appointment on one phone; this also catches clashes that arrive from another device, such as a partner booking the same slot.'] },
  { v: 'v159', items: ['The I’m on my way text now includes the address of the job (Hi Ann, just to let you know I am on my way for your 10:30 appointment at 1 Road, Lincoln). If you have changed the wording in Settings → Calendar, add {address} where you want it, or tap Put the original wording back.'] },
  { v: 'v158', items: ['Back and Done are smarter: if you open a form, quote or certificate from an appointment, Back takes you to that appointment, not to Services or Quotes.'] },
  { v: 'v157', items: ['Appointments now show a Forms for this job list. Tap a past appointment in the calendar to open the forms, quote or certificate that were made for it. This works for new appointments, and for older ones where the customer and day match.'] },
  { v: 'v156', items: ['Quotes now finish with Done – back to quotes (and Back, or deleting a quote, returns to the Quotes list) instead of going to Services.', 'When a quote is marked Accepted, a Schedule into the calendar button appears under it (on the Quotes tab and on the quote itself). It opens a booking already filled in with the customer, address and job, and once saved the quote shows the day it is booked in for. A To schedule filter on the Quotes tab lists accepted jobs that are not in the calendar yet.'] },
  { v: 'v155', items: ['The Invoices tab is now called Sales and has two tabs inside: Invoices and Quotes. The Quotes tab lists every quote with its status (awaiting reply, chase up, accepted, declined), shows how much is waiting for an answer, and has the New quote buttons. Back from a quote returns to the Quotes list.', 'Quote PDF: the total in the black box now lines up with the figures above it, and the faint lines between items sit centred between the rows. With Large text, your business name at the top is bigger too. The Ready to go ahead? section and the terms now stay together: if they will not fit at the bottom of a page they all move to the next page, The price section (table and totals) also stays in one piece and moves to the next page if it would be split. On a quote for any job the first page is spaced out a little so it does not look top-heavy.'] },
  { v: 'v154', items: ['The title under OMB Gas Service at the top now names the section you are in: Services, Calendar, Customers, Invoices, Tools, Settings or Help.', 'Import customers from a spreadsheet has moved to Settings → App → Backup, next to Export customers. It is no longer at the bottom of the Customers list.'] },
  { v: 'v153', items: ['Quote for any job: Start from a previous job now also brings in the items, labour and prices from that quote, so a repeat job needs little typing. Change anything you like.', 'Settings is now the cog at the top right, next to the Help button, which frees up space on the bottom bar. The cog lights up while you are in Settings.'] },
  { v: 'v152', items: ['Customer names now get a capital letter on each word automatically (jane smith becomes Jane Smith), when you type them, import them or book an appointment. Names already saved are tidied once. Names that already have capitals, such as McDonald, are left alone.'] },
  { v: 'v151', items: ['Price list → Labour: an Hourly rate and a Day rate are now there for you. Open them, type your rate, and use them on quotes by entering how many hours or days. Add as many more rates as you like.'] },
  { v: 'v150', items: ['Settings → Calendar → Calendar opens on: choose whether tapping Calendar shows Today, This week or This month first.'] },
  { v: 'v149', items: ['Calendar: import appointments from Google Calendar, Apple Calendar or Outlook. Export your calendar as an .ics file, then choose it in Settings → Calendar → Import. Past events are skipped and nothing is added twice.', 'Labour: price list labour rates are now just a name (Hourly rate, Day rate) and what they are charged per, with no make or model. On a quote, set how many hours or days and the total works itself out.', 'Price list: the categories are now a stacked list. Tap a category (Boiler, Flue, Labour, your own) to open it and see its items, tap again to close. The + Add button is always straight under the open category.', 'Price list: + New category. Add your own categories such as Baths, Toilets or Taps, then fill them with items. They show up when you quote and when you add a line to an invoice.', 'Quote for any job: Start from a previous job. If you have quoted a bathroom install before, pick it from the list and it brings in the job title and what is included, which saves typing.', 'Fixed the page jumping back to the top when you pick the work address (or tick an option) in a form, quote or invoice. It now stays where you were.', 'The Services screen now shows just today’s appointments (and tomorrow’s reminders). The month calendar has moved off it. Find the month and week views on the Calendar tab.'] },
  { v: 'v148', items: ['The Records tab and front screen are now called Services.', 'Calendar is now on the bottom bar, and Annual checks due has moved into it as a Due button next to Today, Week and Month (with the number due). If the calendar is switched off, Annual checks due stays on the Records screen.', 'New: Quote for any job. Bathrooms, radiators, repairs or any other work, not just boilers. Give the job a title and a list of what is included, add items from your price list or your own items and labour, and send a proper quotation PDF with your logo. VAT, large text and the Accepted / Declined chase reminders all work the same as boiler quotes. You can hide it in Settings if you do not want it.'] },
  { v: 'v147', items: ['Invoices: the lines are now headed Work and materials instead of Services, on the invoice screen and above the lines on the PDF. Change the wording in Settings → Invoicing → Heading for the lines on an invoice.'] },
  { v: 'v146', items: ['Invoices: the discount at the bottom can now be £ off or % off. A percentage shows on the invoice as, for example, Discount (10%).'] },
  { v: 'v145', items: ['Invoices: + Add from my price list. Search your price list (boilers, copper, thermostats, labour and so on), tap an item and it is added as an invoice line at its sale price. You can still change the quantity and price.'] },
  { v: 'v144', items: ['Bigger storage: customers, records, invoices and appointments now live in the phone’s database instead of the small browser store that filled up after about a thousand jobs. Your existing data moves across by itself the first time you open the app, and is checked before the old copy is removed.', 'Annual checks due: each one has a Book it in button that opens a booking with the customer, address and job already filled in. Saving it marks the check as booked in.', 'Calendar: Text next customer works through tomorrow’s appointments one tap at a time, opening each customer’s reminder ready to send.', 'Calendar: a Week view with an + Add button for each day, and tomorrow’s appointments show with Text and Email buttons to remind customers (wording and on/off in Settings → Calendar).', 'Customers: Import customers from a spreadsheet (CSV from ServiceM8, Excel or Google Sheets). It shows what will be added and skips anyone already saved.', 'Invoices: Yearly summary and accounts export shows what you invoiced, VAT, paid and owed by month and jobs done, with a CSV download for your accountant.', 'Calendar: picking a customer on a booking no longer jumps the screen back to the top. It stays where you were.', 'Behind the scenes: unused code removed, the calendar code moved to its own file, and a full automatic test suite added. Nothing looks different.', 'On a computer the bottom bar now stays in the same column as the page, the calendar days are shorter, and the Help and Delete draft buttons are easier to tap. The month calendar no longer wobbles sideways on a phone. Settings → App shows how full the saved space on this device is.'] },
  { v: 'v143', items: ['The Text: I’m on my way button only shows when the customer has a mobile number (07… or +44 7…) on the appointment, so you never try to text a landline.'] },
  { v: 'v142', items: ['Calendar: on an open appointment, Text: I’m on my way is now at the top, with a Navigate to button under it that opens the job address in maps.'] },
  { v: 'v141', items: ['Calendar: open an appointment and tap Text: I’m on my way. Your texting app opens with a message to the customer ready to send (on a computer the message is copied instead). Change the wording, or hide the button, in Settings → Calendar.'] },
  { v: 'v140', items: ['Settings → Calendar → Use the calendar: switch the whole calendar on or off. Off removes the calendar, the Schedule in button and the appointment lists, and keeps any appointments you have saved. The separate Show the calendar on the home screen switch is still there for when you want the calendar but not on the front page.'] },
  { v: 'v139', items: ['Calendar: on a booking, the customer is now a search box. Start typing a name, phone number or email and your saved customers come up to tap; or just type the details of someone new.'] },
  { v: 'v138', items: ['The Help guide is brought up to date: new topics on the calendar, boiler quotes, the price list, overdue invoice reminders and Tools, and the existing topics now point to the right Settings tabs.'] },
  { v: 'v137', items: ['Calendar: when you pick a customer, the address of the job is now a list of their saved addresses, with “+ Add a new address” at the bottom. A new address is saved on the customer for next time.'] },
  { v: 'v136', items: ['Calendar: choosing “Other job” now opens a box to say what the job is, with quick buttons for jobs you save. Add or remove those jobs (bathroom install, radiator install and so on) in Settings → Calendar.'] },
  { v: 'v135', items: ['Calendar sync fix: appointments now come through on every device you are signed in on, and there is a Sync now button on the calendar. If you see odd blank invoices after updating, they are cleared automatically.'] },
  { v: 'v134', items: ['New calendar. Today’s appointments and a month calendar now sit on the home screen under your record buttons. Pick a job, tap Schedule in, and fill in the date, time and customer to book it. You can also add appointments from inside the calendar, mark them done, or start the forms straight from an appointment. Appointments sync between every device you are signed in on. Settings has a new Calendar tab to export everything (.ics or spreadsheet).', 'Customer cards now have three tabs: Customer, Navigate and Previous jobs.'] },
  { v: 'v133', items: ['Company logo: it goes back to sitting on a white tile (your logo is still trimmed and sized to fill the tile). The Logo background setting under your logo lets you pick White, Black or Clear.'] },
  { v: 'v132', items: ['Uploading your company or Gas Safe logo now opens the phone’s Files picker instead of going straight to the photo gallery.'] },
  { v: 'v131', items: ['Company logo: when you upload a logo that sits in a white box, the white is now cleared (so the logo fills the tile with no white edging) and it is trimmed to fill the box. Re-upload your logo to use this. There is a Logo background setting (Clear or White) in case a dark logo is hard to see on the dark header.'] },
  { v: 'v130', items: ['Settings: the tabs are now stacked in two rows of three, so Tools and App are no longer hidden off the side of the screen on a phone.', 'Settings: the Payment reminders section was showing on every tab; it now only shows under Invoicing.'] },
  { v: 'v129', items: ['Settings → App → Records to show: switch off the record types you do not use (for example air conditioning commissioning until you are qualified). They disappear from the home screen and the Forms for this visit list, and come back when you switch them on. Records you have already made are kept.', 'Every button now has a capital letter on each word.'] },
  { v: 'v128', items: ['Price list: the categories (Boiler, Flue, Labour, Fittings and so on) are now tabs in one row under the mark-up box. Swipe along them and tap one to see its items.', 'Price list: on the Boiler tab you now see the makes first (Worcester Bosch, Ideal, Vaillant and so on). Tap a make to see its models, and + Add a boiler adds a new one under that make.', 'Price list: a new + Add a make button on the Boiler tab lets you add a boiler make that is not in the list (for example Vokera or Ferroli), then fill in its first model.'] },
  { v: 'v127', items: ['Invoice screen: the Paid tick (and Paid by) is now at the top, under the View invoice button, so you no longer scroll to the bottom to mark an invoice paid.'] },
  { v: 'v126', items: ['Overdue invoices: the day after an invoice passes its payment terms, the home screen asks if you want to send a payment reminder. Say Yes and the reminder email opens with the invoice attached; say No and it asks if the invoice has been paid, or to ask again in 7 days. Nothing is sent without you.', 'Every unpaid invoice now has a Send payment reminder button, and the Invoices list has an Overdue filter (oldest first).', 'The reminder wording can be edited, or the questions turned off, in Settings → Invoicing → Payment reminders.'] },
  { v: 'v125', items: ['The quote chase message (Chase by email and Chase by text) can now be edited in Settings → Quotes, with a button to put the original wording back.'] },
  { v: 'v124', items: ['Settings: Tools now has its own tab (choose which tools show), so Reminders only holds the annual check reminders.'] },
  { v: 'v123', items: ['On a computer, the Open the email button (and the quote chase email button) now opens your email in a new browser tab, so the app stays where you were. Phones are unchanged.'] },
  { v: 'v122', items: ['Settings is now split into tabs across the top: Business (with your bank details, branding, Gas Safe logo and engineer), Invoicing, Quotes, Reminders (with the tools) and App (backup, updates and your account). Nothing has been removed.'] },
  { v: 'v121', items: ['Sharing from Chrome on a Mac: the Mac share menu only offers AirDrop and Messages for PDFs, so the app now skips it and goes straight to the steps box (PDF saved, Open the email, drag the PDF in). Phones, Safari and Windows are unchanged.'] },
  { v: 'v120', items: ['When you go back into a finished record, the button now says Open documents instead of Create documents, because they have already been made. New records still say Create documents.'] },
  { v: 'v119', items: ['The Serial number boxes now have a Copy button too, next to the Gas Council number one.'] },
  { v: 'v118', items: ['Gas Council (GC) number boxes now have a Copy button beside them, so you can paste the number straight into another app to look up the readings.'] },
  { v: 'v117', items: ['Emailing from a PC or Mac: after the PDF is saved, a box now walks you through opening the email and attaching it from your Downloads folder, with a note on setting your default email program. On phones it works as before.'] },
  { v: 'v116', items: ['Price list: more common boilers added. Worcester Greenstar 2000 and 8000 Style (plus the 30kW 8000 Life), Ideal Logic Air, Vaillant ecoFIT pure and sustain (plus the 38kW ecoTEC plus), Viessmann Vitodens 050-W, Alpha E-Tec and E-Tec Plus, and Potterton Assure. If you already have a saved price list they are added to it once, with the cost left blank for you to fill in. Your own prices are not touched.'] },
  { v: 'v115', items: ['Legionella: the Showers fitted question has moved to sit directly above the shower head check, on the risk checks page. If you choose None, the shower head check is hidden.'] },
  { v: 'v114', items: ['Legionella: the stored hot water box is now called Temperature setting of stored hot water.'] },
  { v: 'v113', items: ['Price list: prices that work out to part pounds now show two decimals (for example £1427.40, not £1427.4).'] },
  { v: 'v112', items: ['Addresses: the first letter of each word is now a capital automatically in every address box (customer, job, invoice and your own business address). The postcode is still all capitals.'] },
  { v: 'v111', items: ['Quotes are no longer marked Requires invoice. A finished quote now shows Awaiting reply, and on the Ready to send card you can tick Accepted or Declined (like Paid). After 14 days with no answer it turns red as Chase up, the home screen tells you, and there are Chase by email and Chase by text buttons with a ready-written message.'] },
  { v: 'v110', items: ['There is now an Edit button next to Open on each finished record (quotes included), so you can go back in and change it, then make the PDF again.'] },
  { v: 'v109', items: ['Fix: the file that lets the app work offline and check its version had been saved empty by mistake in the last few updates, so Settings showed the version as unknown or offline. It is restored.'] },
  { v: 'v108', items: ['Text boxes (addresses, notes and so on) now grow to fit what is in them, so there is no scrolling inside a box.'] },
  { v: 'v107', items: ['Quotes: the writing on the quote is a little bigger as standard, and there is a new Text size choice (Normal or Large) at the bottom of the Extras and labour step for older customers. Both still fit on 3 pages.'] },
  { v: 'v106', items: ['Quotes: the Extras and labour page is tidier. Added items are compact with a small ✕ to remove them, the price list search only opens when you tap + From price list and closes after you pick, and the labour and total boxes are slimmer.'] },
  { v: 'v105', items: ['Price list: boilers show their warranty length in the list and in the quote search, and picking one fills in the warranty on the front of the quote. Set it per boiler in the price list (Baxi 600 and 800 are filled in already).'] },
  { v: 'v104', items: ['Quotes: once you pick a boiler or an extra from the price list, the list of matches closes up again.'] },
  { v: 'v103', items: ['Quotes: when you type an item and a price on a quote, a Commit to price list tick appears. Tick it to save the item to your price list (under Other). Nothing is added unless you tick it.'] },
  { v: 'v102', items: ['Quotes: an item you type on a quote with a price is now added to your price list (under Other) so you can find it next time. Items saved before are moved into the price list.'] },
  { v: 'v101', items: ['Settings reordered into the order you set things up: business details, branding, Gas Safe logo, engineer, invoice and bank details, prices, quotes, then tools, reminders, backup, sample data and app version.'] },
  { v: 'v100', items: ['Settings: your business details now sit straight under Send feedback, since they are the first thing to set up.'] },
  { v: 'v99', items: ['New: a Price list in Settings → Quotes. Items are in categories (Boiler, Flue, Labour, Copper & pipe, Fittings, Controls & thermostats and more). Give each its make, model, your cost and a mark-up % (one standard mark-up, one per category, or one per item) and the sale price works itself out. You can also fix a price. It starts with boiler models, flue kits, labour and extras from the ServiceM8 template, and you can fill it in with Excel instead (download, fill in, import).', 'Quotes: find the boiler with a make dropdown and a search box (type part of the model), and pick the flue kit type, labour and extras from your list. Everything shows your sale price only. Your cost and profit show to you at the bottom of the quote and never on the customer PDF.', 'Quotes: the signature step has gone. Customers accept by replying to the email.'] },
  { v: 'v98', items: ['Fix: + New boiler quote now goes straight into the quote instead of asking you to choose a form. Boiler quote is also on the forms-for-this-visit list when you start from a customer.'] },
  { v: 'v97', items: ['Quotes: the manufacturer warranty now shows as a big dark and gold seal on the front of the proposal (for example 10 YEAR warranty) when you pick one on the boiler step.'] },
  { v: 'v96', items: ['Quotes: the email message now says to reply to the email to go ahead and that you will call to arrange the installation date, and the proposal says the same, so customers can accept with a simple reply.'] },
  { v: 'v95', items: ['New: Boiler quotes. Tap + New boiler quote on the home screen, pick the customer, the boiler and flue, add extras (they are remembered for next time) and labour, and it works out the VAT and makes a proper three-page proposal PDF with a cover, your logo, the price up front, what is included, what happens next and a place for the customer to sign. The what is included list, saved items and terms can be edited in Settings under Quotes.'] },
  { v: 'v94', items: ['Heat loss: each room now shows the radiator ΔT (mean water temperature minus room temperature) for the heating system you picked.'] },
  { v: 'v93', items: ['Heat loss quick form trimmed right back: room type, size, sheltered or exposed and window type only. Room temperature and draughts come from the room type, and the outside temperature and boiler allowance are tucked away in a fold-out.'] },
  { v: 'v92', items: ['Heat loss: new rooms now use a quick form like the other apps (room type, length, width, height, sheltered or exposed, window type) and give a range from well insulated to poorly insulated. The radiator sizes use the higher figure and still follow the heating system you pick. Tap Enter the walls, windows and loft myself on a room for the detailed version.'] },
  { v: 'v91', items: ['Heat loss tool made simpler: Air changes per hour is replaced by a plain Draughts choice (Well sealed, Normal, Draughty), the U-values are gone from the wall, glazing, roof and floor lists, and two boxes have friendlier names (Coldest outside temperature, Boiler allowance).'] },
  { v: 'v90', items: ['The Boiler commissioning checklist has been taken off the menus for now. Anything already saved still opens.'] },
  { v: 'v89', items: ['Settings now has Add sample data: two made-up customers and a completed example of every form, so you can open them and see how the forms and PDFs look. Remove sample data clears them again.'] },
  { v: 'v88', items: ['Boiler commissioning checklist: pick the system cleaner and inhibitor from common brands and products (Fernox, Sentinel, Adey), or choose Other and type it. Anything you type is remembered as a button for next time.'] },
  { v: 'v87', items: ['The one-tap button on the forms-for-this-visit screen is now called Landlord visit, so it is clear it ticks just the gas check, boiler service and Legionella forms.'] },
  { v: 'v86', items: ['New form: Boiler commissioning checklist for a new boiler installation. It records compliance and Boiler Plus options, water quality, operating readings, condensate, combustion readings and customer handover, and makes a PDF in the same look as your other certificates. There is a price for it in Settings.'] },
  { v: 'v85', items: ['The gas rate calculator now starts blank on each new certificate, so the readings from the last job are not left in the boxes.'] },
  { v: 'v84', items: ['Defects: one-tap N/A, None taken or Customer advised under Remedial action taken (and N/A under a Legionella recommendation), so you do not have to type when there is nothing to say.'] },
  { v: 'v83', items: ['The Tools button in the bottom bar now has a spanner icon.'] },
  { v: 'v82', items: ['Tools now has its own button in the bottom bar, between Invoices and Settings. It disappears if you turn all the tools off in Settings.'] },
  { v: 'v81', items: ['Tools report: tick which calculator results go in the PDF, with Select all and Select none. Saved reports and the PDF only include what is ticked.'] },
  { v: 'v80', items: ['A fresh look: new OMB flame logo and icon, cleaner type, and a more polished feel throughout. Everything works the same.'] },
  { v: 'v79', items: ['Customer card: each property address now has its own address box and postcode box, with an Add another property button (and Remove).'] },
  { v: 'v78', items: ['Tools: opening Tools from the front page no longer shows the last customer you used it for.'] },
  { v: 'v77', items: ['Pipe sizing now uses the published BS 6891 copper pipe capacity table (interpolated between lengths) instead of a fitted formula. Sizes and the step-down figures are now on the safe side of the table.'] },
  { v: 'v76', items: ['Tools: a Show workings out button on each calculator, so you can follow every step of the sums.','Pipe sizing now divides your kW by 10.6 for the gas rate, and its pressure drop on larger pipes is fitted to the reference app.'] },
  { v: 'v75', items: ['Gas pipe sizing now shows how many metres of the bigger pipe you need nearest the meter before the rest of the run can drop a size.'] },
  { v: 'v74', items: ['Tools report: search for the customer, pick their property from a list, and tap Open report once the PDF is made.'] },
  { v: 'v73', items: ['The Tools button on the home screen now matches the other buttons.'] },
  { v: 'v72', items: ['Open a customer and tap Tools and calculation report. Their name, phone, email and property go at the top of the PDF report, and Same property is ticked for you. You can save the results on their card and open the PDF again later.'] },
  { v: 'v71', items: ['Tools: tick Same property and results carry from one calculator to the next (gas rate or heat loss into pipe sizing, pipe sizing into the tightness test).','Tools: create a PDF report of everything you have calculated, with your details and the customer at the top.'] },
  { v: 'v70', items: ['New tool: Tightness test volume. Works out the installation volume and the pressure drop allowed under the new IGEM/UP/1B Edition 4 rules that start on 1 October 2026.'] },
  { v: 'v69', items: ['You can now hide any of the Tools you do not use, in Settings.'] },
  { v: 'v68', items: ['In Tools, tap the heart to pin a calculator to the top.'] },
  { v: 'v67', items: ['In Tools, the calculators you use most move to the top.'] },
  { v: 'v66', items: ['New Tools section on the home screen: gas rate calculator, gas pipe sizing, and room-by-room heat loss with radiator sizes that change with your flow and return temperatures.','Customer search now finds invoice numbers and certificate numbers too.'] },
  { v: 'v65', items: ['The line on Annual checks due now reads "Reminder sent by email" instead of "Emailed automatically".'] },
  { v: 'v64', items: ['Annual checks due now shows "Reminder sent by email" with the date when an automatic reminder has gone to a customer.'] },
  { v: 'v63', items: ['The Annual checks due page now says whether automatic emails are on, so you know if you need to send anything yourself.'] },
  { v: 'v62', items: ['Legionella risk assessments now appear in Annual checks due, and in the automatic reminder emails, using the next assessment date on the record.'] },
  { v: 'v61', items: ['The Annual checks due button on the home screen now matches the other buttons.'] },
  { v: 'v60', items: ['Automatic reminder emails. Turn them on in Settings and customers with an email address get a reminder about 8 weeks before their gas check or boiler service is due, and again at 2 weeks.', 'Replies come to your own email. Every email has an unsubscribe link, and you can switch it off for any customer.', 'Booked in, Not needed and Stop now sync between your devices and stop the automatic emails too.', 'Fixed: editing a customer no longer removes their favourite heart.'] },
  { v: 'v59', items: ['New: Annual checks due. A button on the Records screen lists gas safety checks and boiler services coming up, or overdue.', 'Tap Text, WhatsApp or Email and the reminder opens on your phone ready to send, using the customer’s details. Nothing is sent without you pressing send.', 'Mark each one Booked in or Not needed, or stop reminders for a property. Change the wording and how early they show in Settings.'] },
  { v: 'v58', items: ['Help guide added. Tap the ? at the top of any screen, or find it in Settings.', 'This What’s new list.', 'Invoices: start typing a client name and matching customers appear. Tap one to fill in their details.', 'Invoices: tap a saved property for that customer, or start typing an address to see saved ones.', 'Send feedback: report a fault, make a suggestion or ask a question from Settings or the Help guide.'] },
  { v: 'v57', items: ['The gas rate timer can now be started before any meter readings are entered.', 'Adding a line to an invoice no longer jumps to the bottom. You stay where you are and the new line is ready to type in.'] },
  { v: 'v56', items: ['You can now open and view an invoice PDF from a customer’s record and from the ready-to-send box, not just edit it.'] },
  { v: 'v55', items: ['Addresses no longer end up with double commas on invoices.', 'Every address now has its own postcode box.'] },
  { v: 'v54', items: ['Boiler service PDF: the flue gas line now says “See results below (Combustion Analyser Readings)”.'] },
  { v: 'v53', items: ['Boiler service PDF: the column once called “Failure details” is now “Further information”.'] },
  { v: 'v52', items: ['“Update app now” is more reliable. It clears the saved copy and loads the newest version.'] },
  { v: 'v51', items: ['The App version box and Update app now button are now at the top of Settings.'] },
  { v: 'v50', items: ['Boiler service: the system filter questions now come after the appliance checks, so the form flows better.'] },
  { v: 'v48', items: ['Backups can now be protected with a password.', 'Bank details are left out of backup files.'] },
  { v: 'v47', items: ['A monthly reminder to back up your data.'] },
  { v: 'v46', items: ['If your sign-up email does not arrive, there is now a resend button.'] }
];
function newsHtml(n) {
  return NEWS.slice(0, n || NEWS.length).map(x => `<div class="card"><div class="t" style="margin-bottom:6px">${x.v}</div><ul style="margin:0;padding-left:20px">${x.items.map(i => `<li style="margin-bottom:6px">${i}</li>`).join('')}</ul></div>`).join('');
}
